items[0].json.aiBody = JSON.stringify({ model: "gpt-4o", temperature: 0.1, messages: [{role: "system", content: "Eres el Architect de Zyndrix. Tu respuesta es técnica, estructurada y visualmente impactante. Usa Markdown."}, {role: "user", content: prompt}] });
